// Company-session schedule data for the landing page.
//
// SOURCE OF TRUTH: src/data/ugm-icd-2026/LO_data/UGM-ICD-sessions.yaml
// Regenerated by `bun run sync:data` → src/data/ugm-icd-2026/stage-sessions.json.
// Do NOT edit the YAML or the generated JSON by hand. This module only reads
// the generated runtime data (`stageSessions`, `companies`, `booths`, `event`).

import { event, stageSessions, companies, booths } from '@/lib/data';

export interface ScheduleCardData {
  id: string;
  speakerName: string;
  speakerTitle: string;
  companyName: string;
  companyShortName: string;
  companyId: string;
  boothCode: string | null;
  logo: string | null;
  photo: string | null;
}

export interface ScheduleSlot {
  time: string;
  cards: ScheduleCardData[];
}

export interface ScheduleDayData {
  id: string;
  date: string;
  dayNumbers: string[];
  activeDayIndex: number;
  badge: string;
  slots: ScheduleSlot[];
}

/** Local logo overrides for the companies that appear in the company sessions. */
const LOGO_BY_COMPANY: Record<string, string> = {
  odoo: '/landing/companies/logos/odoo-purple-logo-for-white-background1.png',
  'pt hutama karya infrastruktur':
    '/landing/companies/logos/gold-logo-pt-hutama-karya-infrastruktur-photoroom1.webp',
  'pt astra international tbk':
    '/landing/companies/logos/gold-logo-pt-astra-international1.webp',
  'paragon corps': '/landing/companies/logos/logo-paragoncorp2.webp',
  'pt bank negara indonesia (persero) tbk': '/landing/companies/logos/logo-bni-png1.png',
  'pt zurich indonesia tbk': '/landing/companies/logos/zurich1.png',
};

const normalizeName = (value: string) => value.trim().replace(/\s+/g, ' ').toLowerCase();

/** "2026-11-28T11:30:00+07:00" → "11.30" */
const formatTime = (iso: string) => iso.slice(11, 16).replace(':', '.');

const companyById = new Map(companies.map((company) => [company.id, company]));
const boothByCompanyId = new Map(
  booths
    .filter((booth) => booth.companyId)
    .map((booth) => [booth.companyId as string, booth.code]),
);

export const scheduleDays: ScheduleDayData[] = event.days.map((day, dayIndex) => {
  const sessions = stageSessions
    .filter((session) => session.dayId === day.id)
    .sort((a, b) => a.start.localeCompare(b.start));

  const slots: ScheduleSlot[] = sessions.map((session) => {
    const company = companyById.get(session.companyId);
    const companyName = company?.name ?? session.companyId;
    const companyShortName = company?.shortName ?? companyName;
    const logo = LOGO_BY_COMPANY[normalizeName(companyName)] ?? null;
    const boothCode = boothByCompanyId.get(session.companyId) ?? null;
    const speakers =
      session.speakers.length > 0
        ? session.speakers
        : [{ name: 'Speaker TBA', title: 'Company Session' }];

    return {
      time: `${formatTime(session.start)}-${formatTime(session.end)}`,
      cards: speakers.map((speaker, speakerIndex) => ({
        id: `${session.id}-${speakerIndex}`,
        speakerName: speaker.name,
        speakerTitle: speaker.title,
        companyName,
        companyShortName,
        companyId: session.companyId,
        boothCode,
        logo,
        photo: null,
      })),
    };
  });

  return {
    id: day.id,
    date: `${day.label} November`,
    dayNumbers: event.days.map((entry) => entry.label),
    activeDayIndex: dayIndex,
    badge: dayIndex === 0 ? 'Today' : 'Tomorrow',
    slots,
  };
});
